from __future__ import annotations

import pytest

from notes.models import Note, generate_id

# ---------------------------------------------------------------------------
# Fixtures
# ---------------------------------------------------------------------------

@pytest.fixture
def a_note() -> Note:
    return Note(id="abc123", title="Hello", body="World")

@pytest.fixture
def a_tagged_note() -> Note:
    return Note(id="def456", title="Tagged", body="Content", tags=["a", "b"])

# ---------------------------------------------------------------------------
# Tests – dataclass basics
# ---------------------------------------------------------------------------

def test_note_creation(a_note: Note) -> None:
    assert a_note.id == "abc123"
    assert a_note.title == "Hello"
    assert a_note.body == "World"
    assert a_note.tags == []


def test_note_tags(a_tagged_note: Note) -> None:
    assert a_tagged_note.tags == ["a", "b"]


def test_note_frozen(a_note: Note) -> None:
    with pytest.raises(AttributeError):
        a_note.title = "changed"  # type: ignore[misc]


def test_search_text(a_note: Note) -> None:
    assert a_note.search_text() == "Hello World"


def test_search_text_with_tags(a_tagged_note: Note) -> None:
    assert a_tagged_note.search_text() == "Tagged Content"

# ---------------------------------------------------------------------------
# Tests – serialization (to_dict / from_dict)
# ---------------------------------------------------------------------------

def test_to_dict(a_note: Note) -> None:
    d = a_note.to_dict()
    assert isinstance(d, dict)
    assert d == {"id": "abc123", "title": "Hello", "body": "World", "tags": []}


def test_to_dict_with_tags(a_tagged_note: Note) -> None:
    d = a_tagged_note.to_dict()
    assert d == {"id": "def456", "title": "Tagged", "body": "Content", "tags": ["a", "b"]}


def test_from_dict(a_note: Note) -> None:
    d = a_note.to_dict()
    restored = Note.from_dict(d)
    assert restored == a_note


def test_from_dict_with_tags(a_tagged_note: Note) -> None:
    d = a_tagged_note.to_dict()
    restored = Note.from_dict(d)
    assert restored == a_tagged_note


def test_from_dict_missing_tags_key() -> None:
    d = {"id": "x", "title": "T", "body": "B"}
    note = Note.from_dict(d)
    assert note.tags == []


def test_roundtrip(a_tagged_note: Note) -> None:
    restored = Note.from_dict(a_tagged_note.to_dict())
    assert restored.id == a_tagged_note.id
    assert restored.title == a_tagged_note.title
    assert restored.body == a_tagged_note.body
    assert restored.tags == a_tagged_note.tags
    assert restored.search_text() == a_tagged_note.search_text()

# ---------------------------------------------------------------------------
# Tests – generate_id
# ---------------------------------------------------------------------------

def test_generate_id_length() -> None:
    assert len(generate_id()) == 8


def test_generate_id_uniqueness() -> None:
    ids = {generate_id() for _ in range(100)}
    assert len(ids) == 100

